Object.assign(simple,{immigration:['Flyttar från andra länder','Registrerade flytthändelser till Sverige. Det är inte andelen utrikes födda som bor här.','→'],crime:['Anmälda brott','Antalet brott som har anmälts. Det är inte alla begångna brott eller din personliga risk.','◇']});
const subjects={income:'Inkomsten',employment:'Andelen som arbetar',unemployment:'Arbetslösheten',school:'Andelen behöriga elever',health:'Andelen som mår bra',unsafe:'Otryggheten',poverty:'Andelen med låg inkomst',childPoverty:'Andelen barn i hushåll med låg inkomst',broadband100:'Tillgången till snabbt bredband'};
function theme(m){const s=norm(m.meta.group||'');if(/skol|utbild|studie|forskol/.test(s))return 'Skola';if(/brott|trygg/.test(s))return 'Trygghet';if(/halsa|sjuk|tand|aldre|omsorg/.test(s))return 'Hälsa och omsorg';if(/bredband|mobil|hastighet|teknik/.test(s))return 'Internet och teknik';if(/val|politis/.test(s))return 'Val och politik';if(/peng|ekonom|skatt|arbete|verksamhetskop|kultur/.test(s))return 'Pengar och arbete';if(/foralder|hushall|alder|mannisk|flytt|sverige|fodda/.test(s))return 'Människor';if(/boende|bostad|bebygg|handel|fritid|transport/.test(s))return 'Hem och omgivning';return 'Mer att upptäcka';}
function local(m){const v=m.values[code];return Number.isFinite(v)?v:null;}
function comparable(m){return !m.meta.relativeIndex&&m.meta.unit!=='kategori'&&m.meta.group!=='Osäkerhet'&&(m.meta.rateComparison===true||/%|\/|per |^år$/.test(m.meta.unit||''));}
function relation(m){const v=local(m),r=m.country;if(v==null||!Number.isFinite(r)||r===0||!comparable(m))return null;const delta=(v-r)/Math.abs(r);return Math.abs(delta)<=.03?'same':delta>0?'higher':'lower';}
function verdict(m){const r=relation(m);if(r==='same')return (subjects[m.key]||'Värdet')+' ligger på ungefär samma nivå.';if(r){const big=Math.abs((local(m)-m.country)/Math.abs(m.country))>=.2;return (subjects[m.key]||'Värdet')+' är '+(big?'mycket ':'lite ')+(r==='higher'?'högre.':'lägre.');}if(local(m)==null)return 'Här saknas en lokal uppgift.';if(m.meta.unit==='områden'&&local(m)===0)return 'Inga områden i den här listan.';if(m.meta.relativeIndex)return 'Ett mått för jämförelse mellan kommuner.';if(m.meta.unit==='kategori')return 'En grupp i källans indelning.';return 'Uppgiften finns för kommunen.';}
function label(key,m){return simple[key]?.[0]||m.meta.label;}
function meaning(key,m){return simple[key]?.[1]||(m.meta.relativeIndex?'Flera uppgifter har vägts ihop. Det är ett jämförelsemått. Det är inte procent eller kronor.':m.meta.unit==='kategori'?'Värdet är en kod för en grupp. Koden är inte en poäng. Läs källans förklaring nedanför.':'Här visas '+m.meta.label.toLocaleLowerCase('sv')+'. Läs mer om vad som räknas i förklaringen nedanför.');}
function trend(key,m){const prev=m.previous?.[code],v=local(m);if(!prev||v==null)return '';const diff=v-prev[1],ratio=diff/Math.max(Math.abs(prev[1]),1);if(Math.abs(ratio)<.01)return 'Värdet ligger nära den förra mätningen.';return 'Värdet har '+(ratio>0?'ökat':'minskat')+(Math.abs(ratio)<.1?' lite.':'.');}
function format(v,m){return v==null?'Uppgift saknas':nf.format(v)+' '+(m.meta.unit||'');}
function detail(key,m){const v=local(m),previous=m.previous?.[code];return '<details><summary>Siffror, tid och källa</summary><p><strong>'+esc(D.municipalities[code])+':</strong> '+esc(format(v,m))+'<br><strong>Sverige, samma mätår:</strong> '+esc(format(m.country,m))+'</p>'+(!comparable(m)?'<p>Kommunens antal ska inte jämföras med hela Sveriges total som ett normalvärde för kommunen.</p>':'')+'<p><strong>Mätperiod eller redovisningsår:</strong> '+esc(m.period)+'</p>'+(previous?'<p>Förra tillgängliga mätningen: '+previous[0]+' · '+esc(format(previous[1],m))+'. Ändrade priser, definitioner och vilka som mäts kan påverka skillnaden.</p>':'')+'<p><strong>Källans namn på uppgiften:</strong> '+esc(m.meta.label)+'</p><p>'+esc(m.meta.definition||'Se originalkällan och webbplatsens fullständiga statistik för definitionen.')+'</p><p>Källa: '+esc(m.meta.source||m.meta.sourceTitle||'Kolada / ursprungskälla enligt definitionen')+(m.meta.url?' · <a href="'+esc(m.meta.url)+'" target="_blank" rel="noopener">Öppna källan ↗</a>':'')+'</p><a class="focus-link" href="/focus/?municipality='+code+'&year='+m.year+'">Se kommunen i fokusvyn ↗</a></details>';}
function graphic(key,m){const v=local(m),r=m.country,show=$('showNumbers').checked;
 if(v==null)return '<div class="quiet-graphic"><span aria-hidden="true">…</span> Ingen lokal uppgift</div>';
 if(relation(m)&&v>=0&&r>=0){const max=Math.max(v,r,1);return '<div class="comparison" role="img" aria-label="'+esc(label(key,m)+'. '+verdict(m)+' Jämfört med Sverige.')+'">'+[[D.municipalities[code],v,''],['Sverige',r,'country']].map(([name,n,cl])=>'<div class="bar-row '+cl+'"><div class="bar-label"><span>'+esc(name)+'</span>'+(show?'<span class="value">'+esc(format(n,m))+'</span>':'')+'</div><div class="track"><div class="fill" style="width:'+(n/max*100).toFixed(2)+'%"></div></div></div>').join('')+'</div>';}
 return '<div class="quiet-graphic"><span aria-hidden="true">'+esc(simple[key]?.[2]||'◇')+'</span> '+(show?'<strong class="value">'+esc(format(v,m))+'</strong>':'<span style="font-size:.88rem">Öppna detaljerna för att se värdet.</span>')+'</div>';}
function card(key,m){return '<article class="fact"><p class="tag">'+esc(theme(m))+'</p><h3>'+esc(label(key,m))+'</h3><p class="story">'+esc(verdict(m))+'</p>'+graphic(key,m)+'<p class="meaning">'+esc(meaning(key,m))+'</p>'+(trend(key,m)?'<p class="meaning">'+esc(trend(key,m))+'</p>':'')+'<p class="period">Mätperiod eller redovisningsår: '+esc(m.period)+'</p>'+detail(key,m)+'</article>';}
function renderFacts(){if(!D)return;const q=norm($('metricSearch').value),topic=$('topic').value,all=$('availability').value==='all';const entries=Object.entries(D.metrics).filter(([key,m])=>(all||local(m)!=null)&&(!topic||theme(m)===topic)&&norm(label(key,m)+' '+m.meta.label+' '+theme(m)).includes(q));$('factCards').innerHTML=entries.slice(0,limit).map(([key,m])=>card(key,m)).join('')||'<p class="empty">Ingen uppgift matchar. Prova ett annat ord eller välj ett annat ämne.</p>';$('factCount').textContent='Visar '+Math.min(limit,entries.length)+' av '+entries.length+' uppgifter. '+Object.values(D.metrics).filter(m=>local(m)!=null).length+' av '+Object.keys(D.metrics).length+' har ett lokalt värde.';$('showMore').hidden=limit>=entries.length;}
function highlights(){const keys=['income','school','health','employment','unsafe','broadband100','poverty'];const candidates=keys.filter(k=>D.metrics[k]&&relation(D.metrics[k]));candidates.sort((a,b)=>Math.abs(local(D.metrics[b])/D.metrics[b].country-1)-Math.abs(local(D.metrics[a])/D.metrics[a].country-1));$('highlights').innerHTML=candidates.slice(0,3).map(k=>{const m=D.metrics[k];return '<article class="highlight"><div><span class="symbol" aria-hidden="true">'+simple[k][2]+'</span><h3>'+esc(label(k,m))+'</h3><p>'+esc(verdict(m))+'</p></div><small>'+esc(meaning(k,m))+'</small></article>';}).join('')||'<p>Det saknas jämförbara lokala uppgifter för den snabba bilden. Du kan söka bland uppgifterna nedanför.</p>';quizItems=candidates;quizIndex=0;renderQuiz();}
function renderQuiz(){const key=quizItems[quizIndex%quizItems.length],m=D.metrics[key];$('quizAnswer').textContent='';if(!m){$('quizQuestion').textContent='Här saknas jämförbara uppgifter för en fråga.';$('quizChoices').innerHTML='';$('nextQuestion').hidden=true;return;}$('nextQuestion').hidden=false;$('quizQuestion').textContent=label(key,m)+': är nivån högre, lägre eller ungefär samma här som i Sverige?';$('quizChoices').innerHTML=[['higher','Högre'],['same','Ungefär samma'],['lower','Lägre']].map(([r,text])=>'<button type="button" data-answer="'+r+'" aria-pressed="false">'+text+'</button>').join('');$('quizChoices').querySelectorAll('button').forEach(b=>b.onclick=()=>{const correct=b.dataset.answer===relation(m);$('quizChoices').querySelectorAll('button').forEach(x=>{x.disabled=true;x.setAttribute('aria-pressed',String(x===b));});$('quizAnswer').textContent=(correct?'Precis! ':'Nu vet du! ')+verdict(m)+' '+meaning(key,m);});}
function selectPlace(next){if(!Object.hasOwn(D.municipalities,next))return;code=next;$('municipality').value=code;$('placeTitle').textContent=D.municipalities[code]+', med vanliga ord.';$('focusLink').href='/focus/?municipality='+code;$('scoreLink').href='/score/?q='+encodeURIComponent(D.municipalities[code]);$('placeResults').innerHTML='';$('placeSearch').value='';limit=12;highlights();renderFacts();try{localStorage.setItem('boring-municipality',code);const url=new URL(location.href);url.searchParams.set('municipality',code);history.replaceState(null,'',url);}catch{}}
$('municipality').onchange=()=>selectPlace($('municipality').value);$('placeSearch').oninput=()=>{if(!D)return;const q=norm($('placeSearch').value.trim());if(!q){$('placeResults').innerHTML='';return;}const matches=Object.entries(D.municipalities).filter(([id,name])=>norm(name+' '+id).includes(q)).sort((a,b)=>a[1].localeCompare(b[1],'sv')).slice(0,8);$('placeResults').innerHTML=matches.map(([id,name])=>'<button type="button" data-place="'+id+'">'+esc(name)+'</button>').join('')||'<p>Ingen kommun hittades.</p>';$('placeResults').querySelectorAll('button').forEach(b=>b.onclick=()=>{selectPlace(b.dataset.place);$('municipality').focus();});};$('placeSearch').onkeydown=e=>{if(e.key==='Escape')$('placeResults').innerHTML='';if(e.key==='Enter'){const first=$('placeResults').querySelector('button');if(first)first.click();}};
for(const id of ['topic','availability','metricSearch'])$(id)[id==='metricSearch'?'oninput':'onchange']=()=>{limit=12;renderFacts();};$('showNumbers').onchange=renderFacts;$('showMore').onclick=()=>{limit+=12;renderFacts();};$('nextQuestion').onclick=()=>{quizIndex++;renderQuiz();};
fetch('/data/boring.json.gz').then(async r=>{if(!r.ok)throw Error('Uppgifterna kunde inte hämtas.');let bytes=new Uint8Array(await r.arrayBuffer());if(bytes[0]===31&&bytes[1]===139){if(typeof DecompressionStream==='undefined')throw Error('Webbläsaren behöver uppdateras för att öppna uppgifterna.');return new Response(new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'))).json();}return JSON.parse(new TextDecoder().decode(bytes));}).then(d=>{D=d;for(const [key,m] of Object.entries(d.metrics))m.key=key;$('municipality').innerHTML=Object.entries(d.municipalities).sort((a,b)=>a[1].localeCompare(b[1],'sv')).map(([id,name])=>'<option value="'+id+'">'+esc(name)+'</option>').join('');$('municipality').disabled=false;$('topic').innerHTML='<option value="">Alla ämnen</option>'+[...new Set(Object.values(d.metrics).map(theme))].sort((a,b)=>a.localeCompare(b,'sv')).map(t=>'<option>'+esc(t)+'</option>').join('');let saved;try{saved=localStorage.getItem('boring-municipality')}catch{}const requested=new URLSearchParams(location.search).get('municipality');selectPlace(Object.hasOwn(d.municipalities,requested)?requested:Object.hasOwn(d.municipalities,saved)?saved:'1401');$('content').hidden=false;$('loadStatus').textContent='';}).catch(e=>{$('loadStatus').textContent=e.message+' Du kan fortfarande öppna kartorna och fokusvyn via menyn.';});
